item.command:
/bin/bash -lc "cat > /tmp/rocq117/check <<'EOF'
#"'!/bin/bash
set -o pipefail
piece="${1:-Base}"
case "$piece" in
  Base) marker='"'"'^Lemma wf_env_subst'"' ;;
  Subst) marker='"'^Lemma typing_wf_env'"' ;;
  Syntax) marker='"'^Lemma sub_record_fields'"' ;;
  Congruence) marker='"'^Definition typ_eq_dec'"' ;;
  Markers) marker='"'^Lemma empty_sub_arrow'"' ;;
esac
first="'$(rg -n "$marker" Task.v | cut -d: -f1)
{
  head -9 Task.v
  printf '"'Require Import Scratch.%s.\\n' \""'$piece"
  tail -n +"$first" Task.v
} > /tmp/rocq117/Tail.v
rocq compile -q -R .rocq-deps/Metalib Metalib -R . '"'' -Q /tmp/rocq117 Scratch /tmp/rocq117/Tail.v 2>&1 |
  awk -v off=\""'$((first - 11))" '"'/Tail.v.*, line /{ split("'$0,x,","); split(x[2],n," "); x[2]=" line " n[2]+off; print "Task.v," x[2] "," x[3]; next } { print }'"'
EOF
chmod +x /tmp/rocq117/check
/tmp/rocq117/check"

